import math


def _norm_string(raw, field):
    if field not in raw:
        raise ValueError("missing field: %s" % field)
    value = raw[field]
    if type(value) is not str:
        raise ValueError("%s must be a string" % field)
    value = value.strip()
    if value == "":
        raise ValueError("%s must not be empty" % field)
    return value


def _norm_record(raw):
    if type(raw) is not dict:
        raise ValueError("record must be an object")

    rid = _norm_string(raw, "id")

    if "revision" not in raw:
        raise ValueError("missing revision")
    rev = raw["revision"]
    if type(rev) is not int:
        raise ValueError("revision must be an integer")
    if rev < 0:
        raise ValueError("revision must be >= 0")

    owner = _norm_string(raw, "owner").lower()

    category = _norm_string(raw, "category").lower()
    if category not in ("prepare", "copy", "verify"):
        raise ValueError("invalid category: %s" % category)

    if "tags" not in raw:
        raise ValueError("missing tags")
    if type(raw["tags"]) is not list:
        raise ValueError("tags must be an array")
    tags = []
    for tag in raw["tags"]:
        if type(tag) is not str:
            raise ValueError("tag must be a string")
        t = tag.strip().lower()
        if t == "":
            raise ValueError("tag must not become empty")
        tags.append(t)
    tags = sorted(set(tags))

    if "failures" not in raw:
        raise ValueError("missing failures")
    failures = raw["failures"]
    if type(failures) is not int:
        raise ValueError("failures must be an integer")
    if failures < 0:
        raise ValueError("failures must be >= 0")

    if "total" not in raw:
        raise ValueError("missing total")
    total = raw["total"]
    if type(total) is not int:
        raise ValueError("total must be an integer")
    if total < 1:
        raise ValueError("total must be >= 1")
    if failures > total:
        raise ValueError("failures must be <= total")

    if "lag" not in raw:
        raise ValueError("missing lag")
    lag = raw["lag"]
    if type(lag) is not int:
        raise ValueError("lag must be an integer")
    if lag < 0:
        raise ValueError("lag must be >= 0")

    if "valid" not in raw:
        raise ValueError("missing valid")
    valid = raw["valid"]
    if type(valid) is not bool:
        raise ValueError("valid must be a boolean")

    return {
        "id": rid,
        "revision": rev,
        "owner": owner,
        "category": category,
        "tags": tags,
        "failures": failures,
        "total": total,
        "lag": lag,
        "valid": valid,
    }


def _score(name, rec, offset, sla):
    if name == "objects":
        base = (0 if rec["valid"] else 15) + rec["failures"]
    elif name == "replication":
        base = math.ceil(rec["lag"] / sla)
    elif name == "transfers":
        base = math.ceil(20 * rec["failures"] / rec["total"])
    else:
        raise ValueError("unknown evidence component: %s" % name)
    return max(0, min(20, base + offset))


def transform(payloads, contract):
    if len(payloads) != 1:
        raise ValueError("evidence transform expects exactly one payload")
    arr = payloads[0]
    if type(arr) is not list:
        raise ValueError("evidence input must be an array of records")

    offset = contract["offset"]
    sla = contract["sla"]
    if type(sla) not in (int, float) or not (sla > 0):
        raise ValueError("sla must be a positive number")

    normalized = [_norm_record(r) for r in arr]

    # Validate/merge duplicate (id, revision) pairs across the whole input,
    # including revisions that will not be kept.
    seen = {}
    for rec in normalized:
        key = (rec["id"], rec["revision"])
        sig = (
            rec["id"],
            rec["revision"],
            rec["owner"],
            rec["category"],
            tuple(rec["tags"]),
            rec["failures"],
            rec["total"],
            rec["lag"],
            rec["valid"],
        )
        if key in seen and seen[key] != sig:
            raise ValueError("conflicting records for (id, revision): %r" % (key,))
        seen[key] = sig

    best = {}
    for rec in normalized:
        cur = best.get(rec["id"])
        if cur is None or rec["revision"] > cur["revision"]:
            best[rec["id"]] = rec

    records = []
    for rec in best.values():
        records.append(
            {
                "id": rec["id"],
                "source": contract["name"],
                "owner": rec["owner"],
                "category": rec["category"],
                "tags": rec["tags"],
                "score": _score(contract["name"], rec, offset, sla),
            }
        )

    records.sort(key=lambda r: (r["source"], r["id"]))
    count = len(records)
    score_total = sum(r["score"] for r in records)

    return {
        "name": contract["name"],
        "result": {
            "records": records,
            "count": count,
            "score_total": score_total,
        },
    }

