    for wrapped in payloads:
        for rec in _records_of(wrapped):
            if type(rec) is not dict:
                raise ValueError("record must be an object")
            key = (rec.get("source"), rec.get("id"))
            if key in merged and merged[key] != rec:
                raise ValueError("source/id conflict: %r" % (key,))
            merged[key] = rec
    return sorted(merged.values(), key=lambda r: (r["source"], r["id"]))


