CATEGORY_ORDER = {"prepare": 0, "copy": 1, "verify": 2}


def _records_of(wrapped):
    if type(wrapped) is not dict:
        raise ValueError("component payload must be an object")
    result = wrapped.get("result")
    if type(result) is not dict:
        raise ValueError("component payload must have a result object")
    records = result.get("records")
    if type(records) is not list:
        raise ValueError("component result must have a records array")
    return records


def _merge_all(payloads):
    merged = {}
    for wrapped in payloads:
        for rec in _records_of(wrapped):
            if type(rec) is not dict:
                raise ValueError("record must be an object")
            key = (rec.get("source"), rec.get("id"))
            if key in merged and merged[key] != rec:
                raise ValueError("source/id conflict: %r" % (key,))
            merged[key] = rec
    return sorted(merged.values(), key=lambda r: (r["source"], r["id"]))


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count does not match contract inputs")
    merged = _merge_all(payloads)

    threshold = contract["threshold"]
    only_if_blocking = contract["only_if_blocking"]

    if only_if_blocking:
        has_blocking = any(
            "blocking" in (r.get("tags") or []) and r["score"] >= threshold
            for r in merged
        )
        if not has_blocking:
            merged = []

    nodes = {}
    for rec in merged:
        nid = rec["source"] + ":" + rec["id"]
        nodes[nid] = {
            "id": nid,
            "category": rec["category"],
            "duration": 1 + rec["score"] // 5,
        }

    if not nodes:
        return {
            "name": contract["name"],
            "result": {
                "records": [],
                "blocked": False,
                "waves": [],
                "critical_path": [],
                "makespan": 0,
                "earliest_finish": {},
            },
        }

    for nid, node in nodes.items():
        node["preds"] = sorted(
            other
            for other, o in nodes.items()
            if CATEGORY_ORDER[o["category"]] < CATEGORY_ORDER[node["category"]]
        )

    remaining = set(nodes)
    processed = set()
    waves = []
    while remaining:
        ready = sorted(
            nid
            for nid in remaining
            if all(p in processed for p in nodes[nid]["preds"])
        )
        if not ready:
            raise ValueError("cycle detected in migration graph")
        waves.append(ready)
        for nid in ready:
            remaining.discard(nid)
            processed.add(nid)

    earliest_finish = {}
    for wave in waves:
        for nid in wave:
            preds = nodes[nid]["preds"]
            if preds:
                earliest_finish[nid] = (
                    max(earliest_finish[p] for p in preds) + nodes[nid]["duration"]
                )
            else:
                earliest_finish[nid] = nodes[nid]["duration"]

    makespan = max(earliest_finish.values())

    best_path = {}
    for wave in waves:
        for nid in wave:
            preds = nodes[nid]["preds"]
            if not preds:
                best_path[nid] = [nid]
            else:
                target = earliest_finish[nid] - nodes[nid]["duration"]
                candidates = [p for p in preds if earliest_finish[p] == target]
                chosen = min(candidates, key=lambda p: best_path[p])
                best_path[nid] = best_path[chosen] + [nid]

    max_cat = max(CATEGORY_ORDER[node["category"]] for node in nodes.values())
    sinks = [
        nid
        for nid, node in nodes.items()
        if CATEGORY_ORDER[node["category"]] == max_cat
    ]
    candidates = [nid for nid in sinks if earliest_finish[nid] == makespan]
    critical_path = min(best_path[nid] for nid in candidates)

    records = sorted(merged, key=lambda r: (r["source"], r["id"]))

    return {
        "name": contract["name"],
        "result": {
            "records": records,
            "blocked": False,
            "waves": waves,
            "critical_path": critical_path,
            "makespan": makespan,
            "earliest_finish": earliest_finish,
        },
    }

